type SellerCatalogAppServiceClient interface {
	// ListMyProducts 列出自己店家沒刪除的商品，任何狀態，不看店家曝光；最新建立的在前。
	ListMyProducts(context.Context, *connect.Request[v1alpha1.ListMyProductsRequest]) (*connect.Response[v1alpha1.ListMyProductsResponse], error)
	// GetMyProduct 讀自己店家的商品完整內容（任何狀態，含 etag 與每個 SKU 的庫存）。
	GetMyProduct(context.Context, *connect.Request[v1alpha1.GetMyProductRequest]) (*connect.Response[v1alpha1.GetMyProductResponse], error)
	// CountMyProducts 回自己店家符合篩選的商品數（導覽列的低庫存徽章用 status = ACTIVE、stock_status = LOW）。
	CountMyProducts(context.Context, *connect.Request[v1alpha1.CountMyProductsRequest]) (*connect.Response[v1alpha1.CountMyProductsResponse], error)
	// CreateProduct 建立一個草稿商品（建立一律是草稿；要上架呼叫 SetProductStatus）。
	// 同一家店以同一個 request_id 重送回第一次建立的商品目前的樣子，不重複建立；內容不同回 invalid_argument。
	CreateProduct(context.Context, *connect.Request[v1alpha1.CreateProductRequest]) (*connect.Response[v1alpha1.CreateProductResponse], error)
	// UpdateProduct 整體取代商品的內容（狀態不變；等同 AIP-134 的 update_mask = "*"，沒有 update_mask）：沒有帶的圖片、選項軸與 SKU 組合會被移除；既有 SKU 的庫存不在這裡改（用 AdjustStock、SetStock）。
	// etag 必填（在請求上，因為寫入的 ProductInput 與讀取的 SellerProduct 是不同的型別），與目前版本不符回 aborted 與 VERSION_CONFLICT，不寫入。商品目前是 ACTIVE 時，輸入至少要有一張主圖，否則回 failed_precondition。
	UpdateProduct(context.Context, *connect.Request[v1alpha1.UpdateProductRequest]) (*connect.Response[v1alpha1.UpdateProductResponse], error)
	// SetProductStatus 切換商品狀態：草稿、上架、下架任兩個都能互切，切成目前的狀態也回成功（不改 etag）。
	// 切成 ACTIVE 時商品至少要有一張主圖，否則回 failed_precondition。首次上架寫入 first_publish_time，之後不清除。
	// etag 必填（上架是把看到的內容公開，內容在狀態不變時仍可能被別人改動，規範 §七）。
	SetProductStatus(context.Context, *connect.Request[v1alpha1.SetProductStatusRequest]) (*connect.Response[v1alpha1.SetProductStatusResponse], error)
	// DeleteProduct 刪除商品：從賣家清單消失、不可還原，列保留（訂單與評價仍引用）。已經刪除的也回成功。etag 選填，帶了就檢查。
	DeleteProduct(context.Context, *connect.Request[v1alpha1.DeleteProductRequest]) (*connect.Response[v1alpha1.DeleteProductResponse], error)
	// AdjustStock 以有號變動量調整自己店家某個 SKU 的庫存（進貨加、出貨減）。
	// 同一家店以同一個 request_id 重送且內容相同只生效一次；內容不同回 invalid_argument。調整後不得小於 0，否則回 failed_precondition。不改商品的 etag。
	AdjustStock(context.Context, *connect.Request[v1alpha1.AdjustStockRequest]) (*connect.Response[v1alpha1.AdjustStockResponse], error)
	// SetStock 把自己店家某個 SKU 的庫存設成絕對值（盤點、商品表單輸入庫存），以 expected_quantity 比對現值：
	// 現值不等於預期（期間有訂單扣減或別處調整）回 failed_precondition，不寫入，client 重讀後再決定。
	// 同一家店以同一個 request_id 重送且內容相同只生效一次；內容不同回 invalid_argument。不改商品的 etag。
	SetStock(context.Context, *connect.Request[v1alpha1.SetStockRequest]) (*connect.Response[v1alpha1.SetStockResponse], error)
}

